// Logic template
var calc_output = [];

var picker = parseFloat(picker);
if (UOMSYSTEM == true) { 
    var glu = parseFloat(glu); 
    var cpr = parseFloat(cpr);
}
if (UOMSYSTEM == false) {
    var glu = parseFloat(glu) / 0.0555; 
    var cpr = parseFloat(cpr) * 331.093;
}

if (picker == 1) {
    var cgr = cpr / glu;
    var header = 'Fasting';
    if (cgr < 2) {
        var msg = 'Insulin secretion deficit';
    } else if (cgr > 5) {
        var msg = 'Preserved endogenous insulin secretion';
    } else {
        var msg = 'Impaired endogenous insulin secretion';
    }
} else {
    var cgr = (cpr * 0.0030203) / glu * 100;
    var header = 'Postprandial';
    if (cgr < 2) {
        var msg = 'Loss of β cell function';
    } else {
        var msg = 'Preserved β cell function';
    }
}


// Output
calc_output.push({
    name: 'mini',
    value: cgr.toFixed(2),
    value_text: '',
    message: msg
});
calc_output.push({
    name: '10529_C-Peptide to Glucose Ratio_result',
    value: cgr.toFixed(2),
    value_text: '',
    message: header + ' C-Peptide to Glucose Ratio' + '<br/><br/>' + msg
});
